```js
function drawCharacter(t) {
  const { charX, groundY, s } = layout;
  const pose = currentPose(t);
  ctx.save();
  ctx.translate(charX, groundY);
  ctx.scale(s, s);

  const hip = { x: pose.hipX, y: -128 + pose.hipDrop };

  drawLegs(hip, pose);

  // shoulders/world positions
  const cs = Math.cos(pose.lean), sn = Math.sin(pose.lean);
  const rot = (x,y) => ({ x: hip.x + x*cs - y*sn, y: hip.y + x*sn + y*cs });
  const shoulderFront = rot(-2, -94);
  const shoulderBack = rot(13, -92);

