  ctx.quadraticCurveTo(-13, 5, -3, 10);
  ctx.quadraticCurveTo(-8, 17, -18, 17);
  ctx.quadraticCurveTo(-23, 16, -23, 11);
  ctx.closePath();
  ctx.fill();

  /* mouth */
  if (pose.mouth > 0.2) {
    ctx.fillStyle = "rgba(60,24,16,0.8)";
    ctx.beginPath();
    ctx.ellipse(-8, 18, 4.2, 2.6 * pose.mouth, 0.08, 0, TAU);
    ctx.fill();
  }

  /* nose */
  const nose = ctx.createLinearGradient(-36, 0, -24, 8);
  nose.addColorStop(0, "#f3c49a");
  nose.addColorStop(1, "#d39369");
  ctx.fillStyle = nose;
  ctx.beginPath();
  ctx.moveTo(-25, -5);
  ctx.quadraticCurveTo(-36, 1, -29, 8);
  ctx.quadraticCurveTo(-24, 9, -22, 4);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(120,66,38,0.4)";
  ctx.lineWidth = 1;
  ctx.stroke();

  /* cheek */
  ctx.fillStyle = "rgba(208,105,80,0.16)";
  ctx.beginPath();
  ctx.ellipse(-17, 8, 6.5, 4, -0.2, 0, TAU);
  ctx.fill();

  /* eye */
  ctx.save();
  ctx.translate(-10.5, -6);
  if (eyeOpen < 0.22) {
    ctx.strokeStyle = "#4c2d1a";
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.quadraticCurveTo(0, 1.6, 5.5, 0);
    ctx.stroke();
  } else {
    ctx.save();
    ctx.scale(1, eyeOpen);
    ctx.fillStyle = "#2f2118";
    ctx.beginPath();
    ctx.ellipse(0, 0, 4.1, 4.3, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#6b4a2c";
    ctx.beginPath();
    ctx.arc(-1.2, -0.4, 2.1, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,250,235,0.95)";
    ctx.beginPath();
    ctx.arc(-2.1, -1.8, 1.1, 0, TAU);
    ctx.fill();
    ctx.restore();
    ctx.strokeStyle = "rgba(74,42,22,0.6)";
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(-5.4, -4.8);
    ctx.quadraticCurveTo(0, -7.6, 5.6, -4.4);
    ctx.stroke();
  }
  ctx.restore();

  /* eyebrow */
  ctx.strokeStyle = "#4f2e1a";
  ctx.lineWidth = 2.6;
  ctx.lineCap = "round";
  const browDrop = pose.squint * 2.4;
  ctx.beginPath();
  ctx.moveTo(-18, -13.5 + browDrop * 0.3);
  ctx.quadraticCurveTo(-10, -17 + browDrop, -2, -14 + browDrop * 0.6);
  ctx.stroke();

  /* beanie */
  const beanie = ctx.createLinearGradient(-20, -38, 24, -8);
  beanie.addColorStop(0, "#557a63");
  beanie.addColorStop(0.5, "#3f5d4b");
  beanie.addColorStop(1, "#2c4437");
  ctx.fillStyle = beanie;
  ctx.beginPath();
  ctx.moveTo(-30, -9);
  ctx.bezierCurveTo(-30, -30, -17, -43, -1, -43);
  ctx.bezierCurveTo(15, -43, 30, -30, 30, -9);
  ctx.quadraticCurveTo(0, -3, -30, -9);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(26,42,32,0.45)";
  ctx.lineWidth = 1.3;
  ctx.stroke();

  /* knit ribs */
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(-30, -9);
  ctx.bezierCurveTo(-30, -30, -17, -43, -1, -43);
  ctx.bezierCurveTo(15, -43, 30, -30, 30, -9);
  ctx.quadraticCurveTo(0, -3, -30, -9);
  ctx.closePath();
  ctx.clip();
  ctx.strokeStyle = "rgba(24,40,30,0.25)";
  ctx.lineWidth = 1.2;
  for (let x = -28; x <= 28; x += 5.2) {
    ctx.beginPath();
    ctx.moveTo(x, -46);
    ctx.quadraticCurveTo(x + 1, -24, x + 0.5, -4);
    ctx.stroke();
  }
  ctx.fillStyle = "rgba(255,230,186,0.12)";
  ctx.beginPath();
  ctx.ellipse(-13, -30, 8, 4, -0.5, 0, TAU);
  ctx.fill();
  ctx.restore();

  /* folded band */
  const band = ctx.createLinearGradient(0, -18, 0, -4);
  band.addColorStop(0, "#4d6e58");
  band.addColorStop(1, "#344d3d");
  ctx.fillStyle = band;
  roundRectPath(ctx, -31, -17, 62, 13, 6);
  ctx.fill();
  ctx.strokeStyle = "rgba(26,42,32,0.4)";
  ctx.lineWidth = 1.1;
  ctx.stroke();
  ctx.strokeStyle = "rgba(223,240,218,0.16)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-28, -14.5);
  ctx.lineTo(28, -14.5);
  ctx.stroke();

  /* pom */
  const pom = ctx.createRadialGradient(1, -50, 1, 2, -47, 9);
  pom.addColorStop(0, "#f4dfb0");
  pom.addColorStop(1, "#c9a367");
  ctx.fillStyle = pom;
  ctx.beginPath();
  ctx.arc(2, -47, 7.3, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(94,66,32,0.3)";
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.restore();
}

function drawArm(shoulder, hand, back) {
  const elbow = solveIK(shoulder.x, shoulder.y, hand.x, hand.y, 52, 52, 1);
  const sleeve = back ? "#8f3329" : "#b8483a";
  const sleeveDark = back ? "#71251f" : "#94352b";
  const skin = back ? "#ce9169" : "#e8b489";
  const skinDark = back ? "#b87a53" : "#d1956b";

  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  strokeLine(shoulder, elbow, 23, "rgba(42,20,12,0.38)");
  strokeLine(elbow, hand, 18, "rgba(42,20,12,0.34)");

  const upper = ctx.createLinearGradient(shoulder.x - 12, shoulder.y, shoulder.x + 12, shoulder.y);
  upper.addColorStop(0, sleeve);
  upper.addColorStop(1, sleeveDark);
  strokeLine(shoulder, elbow, 19, upper);

  const fore = ctx.createLinearGradient(elbow.x - 10, elbow.y, elbow.x + 10, elbow.y);
  fore.addColorStop(0, skin);
  fore.addColorStop(1, skinDark);
  strokeLine(elbow, { x: hand.x - (hand.x - elbow.x) * 0.08, y: hand.y - (hand.y - elbow.y) * 0.08 }, 14.5, fore);

  /* rolled sleeve cuff */
  ctx.strokeStyle = back ? "#5f211b" : "#72261f";
  ctx.lineWidth = 3.4;
  const dx = hand.x - elbow.x;
  const dy = hand.y - elbow.y;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len;
  const ny = dx / len;
  ctx.beginPath();
  ctx.moveTo(elbow.x + nx * 7, elbow.y + ny * 7);
  ctx.lineTo(elbow.x - nx * 7, elbow.y - ny * 7);
  ctx.stroke();
}

function drawHand(p, back) {
  const glove = ctx.createRadialGradient(p.x - 2, p.y - 3, 1, p.x, p.y, 9);
  glove.addColorStop(0, back ? "#7a5137" : "#8b5c3d");
  glove.addColorStop(1, back ? "#4f3321" : "#5c3b26");
  ctx.fillStyle = glove;
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, 7.4, 7.9, 0.3, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(41,23,12,0.5)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  ctx.strokeStyle = "rgba(255,213,162,0.22)";
  ctx.lineWidth = 1.1;
  ctx.beginPath();
  ctx.arc(p.x - 1, p.y - 1, 4.4, 2.3, 4.2);
  ctx.stroke();

  /* thumb */
  ctx.fillStyle = back ? "#5b3b26" : "#6d4630";
  ctx.beginPath();
  ctx.ellipse(p.x + 4.6, p.y - 4, 2.8, 3.6, -0.5, 0, TAU);
  ctx.fill();
}

function drawAxe(grip, angle) {
  ctx.save();
  ctx.translate(grip.x, grip.y);
  ctx.rotate(angle);

  /* handle */
  const handle = ctx.createLinearGradient(0, -5.5, 0, 5.5);
  handle.addColorStop(0, "#d0a166");
  handle.addColorStop(0.45, "#a9743e");
  handle.addColorStop(1, "#6f4525");
  ctx.lineCap = "round";
  ctx.strokeStyle = "rgba(44,24,10,0.4)";
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(-15, 0);
  ctx.lineTo(97, 0);
  ctx.stroke();

  ctx.strokeStyle = handle;
  ctx.lineWidth = 7.2;
  ctx.beginPath();
  ctx.moveTo(-15, 0);
  ctx.lineTo(97, 0);
  ctx.stroke();

  ctx.strokeStyle = "rgba(255,220,170,0.35)";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(-12, -2.1);
  ctx.lineTo(94, -2.1);
  ctx.stroke();

  /* butt cap */
  ctx.fillStyle = "#4d2f1a";
  ctx.beginPath();
  ctx.ellipse(-15, 0, 2.6, 5.4, 0, 0, TAU);
  ctx.fill();

  /* grip wrap */
  ctx.strokeStyle = "rgba(62,38,18,0.75)";
  ctx.lineWidth = 2;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-8 + i * 4.5, -4.2);
    ctx.lineTo(-8 + i * 4.5, 4.2);
    ctx.stroke();
  }

  /* steel head */
  const steel = ctx.createLinearGradient(88, -30, 122, 2);
  steel.addColorStop(0, "#eef6f8");
  steel.addColorStop(0.32, "#b9c8cd");
  steel.addColorStop(0.72, "#7f9199");
  steel.addColorStop(1, "#55666e");
  ctx.fillStyle = steel;
  ctx.beginPath();
  ctx.moveTo(88, -7);
  ctx.quadraticCurveTo(93, -19, 101, -32);
  ctx.quadraticCurveTo(112, -36, 122, -27);
  ctx.quadraticCurveTo(121, -12, 115, -3);
  ctx.quadraticCurveTo(103, 3, 91, 3);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(41,54,60,0.55)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  /* socket / eye */
  ctx.fillStyle = "#77878d";
  roundRectPath(ctx, 88, -9, 17, 18, 4);
  ctx.fill();
  ctx.strokeStyle = "rgba(35,46,52,0.55)";
  ctx.lineWidth = 1;
  ctx.stroke();
  ctx.fillStyle = "rgba(30,38,42,0.45)";
  ctx.beginPath();
  ctx.ellipse(97.5, 0, 4, 5.4, 0, 0, TAU);
  ctx.fill();

  /* cutting edge highlight */
  ctx.strokeStyle = "rgba(247,252,253,0.92)";
  ctx.lineWidth = 2.1;
  ctx.beginPath();
  ctx.moveTo(101.5, -32.4);
  ctx.quadraticCurveTo(112, -36, 122, -27);
  ctx.stroke();
  ctx.strokeStyle = "rgba(255,255,255,0.45)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(91, -5);
  ctx.quadraticCurveTo(99, -13, 104, -26);
  ctx.stroke();

  /* blade bevel */
  ctx.strokeStyle = "rgba(66,82,90,0.4)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(96, -3);
  ctx.quadraticCurveTo(104, -10, 108, -24);
  ctx.stroke();

  /* impact glint */
  if (stumpFlash > 0.15) {
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    ctx.strokeStyle = `rgba(255,250,225,${stumpFlash * 0.8})`;
    ctx.lineWidth = 2.6;
    ctx.beginPath();
    ctx.moveTo(101.5, -32.4);
    ctx.quadraticCurveTo(112, -36, 122, -27);
    ctx.stroke();
    ctx.restore();
  }

  ctx.restore();
}
