/* ------------------------------------------------------------------ */
/* swing & impact                                                     */
/* ------------------------------------------------------------------ */

let elapsed = 0;
let hintTimer = 0;

function startSwing() {
  const from = currentPose(elapsed);
  swing.t = 0;
  swing.queued = false;
  swing.hit = false;
  swing.from = from;
  AudioKit.whoosh();
}

function requestChop() {
  if (swing.t < 0 || swing.t >= CHOP.impactAt + 0.045) {
    startSwing();
  } else {
    swing.queued = true;
  }
}

function updateSwing(dt) {
  if (swing.t < 0) return;
  swing.t += dt;
  if (!swing.hit && swing.t >= CHOP.impactAt) {
    swing.hit = true;
    impact();
  }
  if (swing.queued && swing.hit && swing.t >= CHOP.impactAt + CHOP.hold) {
    startSwing();
    return;
  }
  if (swing.t >= CHOP.cycle) {
    swing.t = -1;
    swing.from = null;
  }
}

function impact() {
  const x = layout.stumpX;
  const y = layout.stumpTopY;
  const scale = clamp(layout.s, 0.7, 1.3);

  count += 1;
  stumpFlash = 1;
  crackT = 0.5;
  cutMarks.push({ x: (Math.random() - 0.5) * 34 });
  if (cutMarks.length > 6) cutMarks.shift();

  spawnChips(x, y + 3, 13);
  spawnDust(x, y + 5, 5);
  spawnRing(x, y, 74 * scale);
  addText("+1", x + 6 * scale, y - 26 * layout.s);
  addShake(7.2);

  updateScoreUI(true);
  syncPile();
  AudioKit.chop();
  vibrate(14);

  if (!hasChopped) {
    hasChopped = true;
    hideHintSoon();
  }

  if (count === 10 || count === 25 || count % 50 === 0) {
    showToast(`${formatCount(count)} 장작!`);
    AudioKit.chime();
    spawnSparks(x, y - 8, 26);
    spawnRing(x, y, 128 * scale);
    addShake(5.5);
  }

  saveCountSoon();
}

/* ------------------------------------------------------------------ */
/* effect painting                                                    */
/* ------------------------------------------------------------------ */

function drawEffects() {
  const scale = clamp(layout.s, 0.7, 1.3);

  /* shock rings */
  ctx.save();
  ctx.globalCompositeOperation = "lighter";
  for (const ring of rings) {
    const k = 1 - ring.life / ring.maxLife;
    const alpha = (1 - k) * 0.5;
    ctx.strokeStyle = `rgba(255,225,160,${alpha})`;
    ctx.lineWidth = 2.2 * scale;
    ctx.beginPath();
    ctx.ellipse(ring.x, ring.y, ring.r, ring.r * 0.34, 0, 0, TAU);
    ctx.stroke();
    ctx.strokeStyle = `rgba(255,244,214,${alpha * 0.5})`;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.ellipse(ring.x, ring.y, ring.r * 0.72, ring.r * 0.24, 0, 0, TAU);
    ctx.stroke();
  }
  ctx.restore();

  /* impact flash */
  if (stumpFlash > 0.01) {
    const fx = layout.stumpX;
    const fy = layout.stumpTopY;
    ctx.save();
    ctx.globalCompositeOperation = "lighter";
    const glow = ctx.createRadialGradient(fx, fy, 0, fx, fy, 92 * scale);
    glow.addColorStop(0, `rgba(255,250,224,${0.72 * stumpFlash})`);
    glow.addColorStop(0.26, `rgba(255,220,154,${0.36 * stumpFlash})`);
    glow.addColorStop(1, "rgba(255,190,100,0)");
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(fx, fy, 92 * scale, 0, TAU);
    ctx.fill();

    ctx.strokeStyle = `rgba(255,250,226,${0.7 * stumpFlash})`;
    ctx.lineWidth = 1.6;
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI * (0.08 + i * 0.15);
      const r0 = 10 * scale;
      const r1 = (25 + (i % 3) * 13) * scale;
      ctx.beginPath();
      ctx.moveTo(fx + Math.cos(a) * r0, fy + Math.sin(a) * r0 * 0.5);
      ctx.lineTo(fx + Math.cos(a) * r1, fy + Math.sin(a) * r1 * 0.5);
      ctx.stroke();
    }
    ctx.restore();
  }

  /* dust */
  for (const p of dust) {
    const alpha = Math.max(0, p.life / p.max) * 0.22;
    const grd = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.r);
    grd.addColorStop(0, `rgba(214,190,146,${alpha})`);
    grd.addColorStop(1, "rgba(190,170,130,0)");
    ctx.fillStyle = grd;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, TAU);
