import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true });
const errors = [];

async function open(opts, name) {
  const page = await browser.newPage(opts);
  page.on('pageerror', (e) => errors.push(`${name} PAGEERROR ${e.message}`));
  page.on('console', (m) => {
    if (m.type() === 'error') errors.push(`${name} CONSOLE ${m.text()}`);
  });
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
  await page.waitForTimeout(1000);
  return page;
}

/* ---------- portrait mobile ---------- */
const m = await open(
  {
    viewport: { width: 412, height: 915 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  },
  'mobile'
);

const initial = await m.evaluate(() => ({
  count: window.__woodcutter?.count,
  canvas: [document.querySelector('canvas').width, document.querySelector('canvas').height],
  dpr: devicePixelRatio,
  btn: document.querySelector('#chopBtn').getBoundingClientRect().toJSON(),
  score: document.querySelector('#scoreCard').getBoundingClientRect().toJSON(),
  hint: document.querySelector('#hint').getBoundingClientRect().toJSON(),
  vw: innerWidth,
  vh: innerHeight,
  overflowX: document.documentElement.scrollWidth > innerWidth,
  overflowY: document.documentElement.scrollHeight > innerHeight,
}));
console.log('INITIAL', JSON.stringify(initial));
await m.screenshot({ path: '/tmp/opencode/final-mobile-idle.png' });

/* single tap -> count increments at impact */
await m.locator('#chopBtn').tap();
await m.waitForTimeout(120);
const early = await m.evaluate(() => window.__woodcutter.count);
await m.waitForTimeout(300);
const late = await m.evaluate(() => window.__woodcutter.count);
console.log('SINGLE_TAP early=', early, 'late=', late);
await m.screenshot({ path: '/tmp/opencode/final-mobile-impact.png' });

/* rapid taps */
for (let i = 0; i < 10; i++) {
  await m.locator('#chopBtn').tap();
  await m.waitForTimeout(90);
}
await m.waitForTimeout(2600);
const rapid = await m.evaluate(() => ({
  count: window.__woodcutter.count,
  score: document.querySelector('#scoreValue').textContent,
  hintHidden: document.querySelector('#hint').classList.contains('hide'),
  swingIdle: window.__woodcutter.swing.t < 0,
}));
console.log('RAPID', JSON.stringify(rapid));
await m.screenshot({ path: '/tmp/opencode/final-mobile-after.png' });

/* mute toggle */
const muteBefore = await m.evaluate(() => ({
  pressed: document.querySelector('#muteBtn').getAttribute('aria-pressed'),
  label: document.querySelector('#muteBtn').getAttribute('aria-label'),
}));
await m.locator('#muteBtn').click();
await m.waitForTimeout(200);
const muteAfter = await m.evaluate(() => ({
  pressed: document.querySelector('#muteBtn').getAttribute('aria-pressed'),
  label: document.querySelector('#muteBtn').getAttribute('aria-label'),
}));
console.log('MUTE', JSON.stringify({ muteBefore, muteAfter }));
await m.locator('#muteBtn').click();

/* persistence across reload */
await m.reload({ waitUntil: 'load' });
await m.waitForTimeout(900);
const persisted = await m.evaluate(() => ({
  count: window.__woodcutter.count,
  score: document.querySelector('#scoreValue').textContent,
  stored: localStorage.getItem('woodcutter.count'),
}));
console.log('PERSIST', JSON.stringify(persisted));

/* milestone toast (count 10 already reached; tap once to see 11) */
await m.locator('#chopBtn').tap();
await m.waitForTimeout(600);
const toast = await m.evaluate(() => {
  const el = document.querySelector('#toast');
  return { text: el.textContent, visible: el.classList.contains('show') };
});
console.log('TOAST', JSON.stringify(toast));

/* ---------- desktop ---------- */
const d = await open({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 }, 'desktop');
const dLayout = await d.evaluate(() => ({
  btn: document.querySelector('#chopBtn').getBoundingClientRect().toJSON(),
  score: document.querySelector('#scoreCard').getBoundingClientRect().toJSON(),
  overflowX: document.documentElement.scrollWidth > innerWidth,
  overflowY: document.documentElement.scrollHeight > innerHeight,
}));
console.log('DESKTOP', JSON.stringify(dLayout));
await d.screenshot({ path: '/tmp/opencode/final-desktop.png' });

/* ---------- landscape ---------- */
const l = await open(
  {
    viewport: { width: 844, height: 390 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
  },
  'landscape'
);
const lLayout = await l.evaluate(() => ({
  btn: document.querySelector('#chopBtn').getBoundingClientRect().toJSON(),
  score: document.querySelector('#scoreCard').getBoundingClientRect().toJSON(),
  overflowX: document.documentElement.scrollWidth > innerWidth,
  overflowY: document.documentElement.scrollHeight > innerHeight,
}));
console.log('LANDSCAPE', JSON.stringify(lLayout));
await l.screenshot({ path: '/tmp/opencode/final-landscape.png' });
await l.locator('#chopBtn').tap();
await l.waitForTimeout(500);
await l.screenshot({ path: '/tmp/opencode/final-landscape-chop.png' });

/* ---------- tall + short edge cases ---------- */
const t = await open({ viewport: { width: 360, height: 780 }, deviceScaleFactor: 2 }, 'small');
console.log(
  'SMALL',
  JSON.stringify(
    await t.evaluate(() => ({
      overflowY: document.documentElement.scrollHeight > innerHeight,
      btn: document.querySelector('#chopBtn').getBoundingClientRect().toJSON(),
    }))
  )
);
await t.screenshot({ path: '/tmp/opencode/final-small.png' });

const w = await open({ viewport: { width: 915, height: 412 }, deviceScaleFactor: 2 }, 'wide');
await w.screenshot({ path: '/tmp/opencode/final-wide.png' });

console.log('ERRORS', JSON.stringify(errors));
await browser.close();

