  function tick() {
    frames++;
    if (performance.now() - t0 < 2000) requestAnimationFrame(tick);
    else resolve({ frames, ms: performance.now() - t0, fps: frames / ((performance.now() - t0) / 1000) });
  }
  requestAnimationFrame(tick);
}));
console.log('FPS', JSON.stringify(fps));
const mem = await page.evaluate(() => performance.memory ? { used: Math.round(performance.memory.usedJSHeapSize / 1048576) } : null);
console.log('MEM_MB', JSON.stringify(mem));
await browser.close();
