import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => m.type() === 'error' && errors.push('CONSOLE ' + m.text()));
await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load' });
await page.waitForTimeout(700);
const score = () => page.evaluate(() => document.querySelector('#scoreValue').textContent);
console.log('start', await score());

await page.mouse.click(720, 834);
await page.waitForTimeout(80);
const ripple = await page.evaluate(() => document.querySelectorAll('.ripple').length);
await page.waitForTimeout(600);
console.log('mouse click ->', await score(), 'ripple created:', ripple);

await page.keyboard.press('Space');
await page.waitForTimeout(600);
console.log('space ->', await score());

await page.locator('#chopBtn').focus();
await page.keyboard.press('Enter');
await page.waitForTimeout(600);
console.log('enter (focused) ->', await score());

/* clicking mute must not chop */
await page.locator('#muteBtn').click();
await page.waitForTimeout(500);
console.log('after mute click ->', await score());

/* resize mid-game */
await page.setViewportSize({ width: 844, height: 390 });
await page.waitForTimeout(500);
const layout = await page.evaluate(() => ({
  btn: document.querySelector('#chopBtn').getBoundingClientRect().toJSON(),
  overflow: document.documentElement.scrollWidth > innerWidth || document.documentElement.scrollHeight > innerHeight,
}));
console.log('resized', JSON.stringify(layout));
await page.screenshot({ path: '/tmp/opencode/input-resized.png' });
